import openpyxl


class ExcelProcessor:
    def __init__(self):
        pass

    def read_excel(self, file_name):
        data = []
        try:
            workbook = openpyxl.load_workbook(file_name)
            sheet = workbook.active
            for row in sheet.iter_rows(values_only=True):
                data.append(row)
            workbook.close()
            return data
        except:
            return None

    def write_excel(self, data, file_name):
        try:
            workbook = openpyxl.Workbook()
            sheet = workbook.active
            for row in data:
                sheet.append(row)
            workbook.save(file_name)
            workbook.close()
            return 1
        except:
            return 0

    def is_numeric_string(self, value):
        return str(value).isdigit()

    def is_valid_for_processing(self, data, n):
        return data is not None and n < len(data[0])

    def transform_row(self, row, n):
        new_row = list(row)
        value = row[n]
        if self.is_numeric_string(value):
            new_row.append(value)
        else:
            new_row.append(str(value).upper())
        return new_row

    def get_processed_file_name(self, save_file_name):
        return save_file_name.split('.')[0] + '_process.xlsx'

    def process_excel_data(self, n, save_file_name):
        data = self.read_excel(save_file_name)
        if not self.is_valid_for_processing(data, n):
            return 0
        new_data = []
        for row in data:
            new_row = self.transform_row(row, n)
            new_data.append(new_row)
        new_file_name = self.get_processed_file_name(save_file_name)
        success = self.write_excel(new_data, new_file_name)
        return success, new_file_name
